# 存储性能持续监控系统
import time
import subprocess
import json
from datetime import datetime

class StoragePerformanceMonitor:
    def __init__(self):
        self.metrics_history = []
        self.thresholds = {
            'iops': 80000,
            'latency_ms': 10,
            'throughput_mb': 100
        }

    def collect_metrics(self):
        """收集存储性能指标"""
        try:
            # 使用kubectl获取存储指标
            cmd = "kubectl top pods --no-headers"
            result = subprocess.run(cmd, shell=True, capture_output=True, text=True)

            metrics = {
                'timestamp': datetime.now().isoformat(),
                'cpu_usage': [],
                'memory_usage': [],
                'storage_metrics': self.get_storage_metrics()
            }

            return metrics
        except Exception as e:
            print(f"指标收集失败: {e}")
            return None

    def get_storage_metrics(self):
        """获取存储相关指标"""
        # 这里可以集成具体的存储监控数据源
        return {
            'iops_current': 45000,
            'latency_ms': 2.5,
            'throughput_mb': 150,
            'utilization_pct': 75
        }

    def analyze_performance(self, metrics):
        """分析性能状况"""
        storage = metrics['storage_metrics']
        alerts = []

        if storage['iops_current'] > self.thresholds['iops']:
            alerts.append({
                'type': 'high_iops',
                'severity': 'warning',
                'message': f"IOPS过高: {storage['iops_current']}"
            })

        if storage['latency_ms'] > self.thresholds['latency_ms']:
            alerts.append({
                'type': 'high_latency',
                'severity': 'critical',
                'message': f"延迟过高: {storage['latency_ms']}ms"
            })

        return alerts

    def run_continuous_monitoring(self, interval=300):
        """持续监控循环"""
        print("开始持续性能监控...")
        while True:
            try:
                metrics = self.collect_metrics()
                if metrics:
                    alerts = self.analyze_performance(metrics)
                    if alerts:
                        self.handle_alerts(alerts)
                    self.metrics_history.append(metrics)

                time.sleep(interval)
            except KeyboardInterrupt:
                print("监控已停止")
                break
            except Exception as e:
                print(f"监控异常: {e}")
                time.sleep(60)

